/**
 * Sky-dating golden: the TS port of dateSky must reproduce the Python
 * reference's windows and search funnel. Both run the SAME specs (from
 * datesky-golden.json, generated by python/export_datesky_golden.py) on the
 * same data, so the bisected edges match to well under the tolerance. The
 * calendar helpers (julianDay with a calendar, calendarDate) are pinned by
 * the same fixture.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Engine } from "../src/chart.js";
import { calendarDate, julianDay, type Calendar } from "../src/core.js";
import { loadNodeData } from "../src/node-loader.js";
import { dateSky, type SkyConstraint } from "../src/datesky.js";

const here = dirname(fileURLToPath(import.meta.url));
const G = JSON.parse(readFileSync(join(here, "../../test/datesky-golden.json"), "utf8"));
const data = loadNodeData(join(here, "../../data"), "embedded", "full");
const eng = new Engine(data);

let checks = 0;
let failures = 0;
let worst = 0;
const TOL = 1e-6; // days (~0.09 s)

const ok = (cond: boolean, msg: string): void => {
  checks++;
  if (!cond) { failures++; console.error(`FAIL ${msg}`); }
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
for (const c of G.cases as any[]) {
  const o = c.options ?? {};
  const got = dateSky(eng, c.constraints as SkyConstraint[], c.jd0, c.jd1, {
    zodiac: o.zodiac, pad: o.pad, maxWindows: o.max_windows,
  });
  const want = c.result;
  ok(got.truncated === want.truncated, `${c.id}: truncated`);
  ok(got.windows.length === want.windows.length,
    `${c.id}: got ${got.windows.length} windows, want ${want.windows.length}`);
  if (got.windows.length === want.windows.length) {
    for (let i = 0; i < got.windows.length; i++) {
      for (const k of ["start", "end"] as const) {
        const diff = Math.abs(got.windows[i][k] - want.windows[i][k]);
        if (diff > worst) worst = diff;
        ok(diff <= TOL, `${c.id} window ${i}.${k}: diff ${diff} d`);
      }
    }
  }
  ok(got.funnel.length === want.funnel.length, `${c.id}: funnel length`);
  for (let i = 0; i < Math.min(got.funnel.length, want.funnel.length); i++) {
    const g = got.funnel[i];
    const w = want.funnel[i];
    ok(g.constraint === w.constraint, `${c.id} funnel ${i}: scan order`);
    ok(g.label === w.label, `${c.id} funnel ${i}: label "${g.label}" vs "${w.label}"`);
    ok(g.windows === w.windows, `${c.id} funnel ${i}: ${g.windows} windows vs ${w.windows}`);
    ok(Math.abs(g.days - w.days) <= 1e-4, `${c.id} funnel ${i}: days ${g.days} vs ${w.days}`);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
for (const r of G.calendar as any[]) {
  const cal = r.calendar as Calendar;
  const jd = julianDay(r.year, r.month, r.day, r.hour, 0, 0, cal);
  ok(jd === r.jd, `julianDay ${r.year}-${r.month}-${r.day} ${cal}: ${jd} vs ${r.jd}`);
  const back = calendarDate(r.jd, cal);
  ok(back.year === r.back.year && back.month === r.back.month && back.day === r.back.day,
    `calendarDate ${r.jd} ${cal}: ${JSON.stringify(back)}`);
  ok(Math.abs(back.hour - r.back.hour) < 1e-9, `calendarDate ${r.jd} ${cal}: hour`);
}

// Argument checks mirror the reference's.
const jd0 = julianDay(2024, 1, 1);
const bad: Array<[SkyConstraint[], string]> = [
  [[], "no constraints"],
  [[{ body: "sun" } as unknown as SkyConstraint], "no arc"],
  [[{ body: "sun", sign: "Ophiuchus" }], "unknown sign"],
  [[{ sign: "Leo" } as unknown as SkyConstraint], "no quantity"],
  [[{ body: "sun", from: 10, to: 10 }], "empty arc"],
  [[{ body: "sun", lon: 0, orb: 175 }], "arc too wide"],
];
for (const [cons, why] of bad) {
  let threw = false;
  try { dateSky(eng, cons, jd0, jd0 + 10); } catch (e) { threw = e instanceof RangeError; }
  ok(threw, `should reject: ${why}`);
}

console.log(`${checks} checks, ${failures} failures`);
console.log(`worst edge diff: ${worst.toExponential(2)} d`);
process.exit(failures === 0 ? 0 : 1);
